}

Method.Source:
/// <summary>
/// PaffH 24.10.23
/// </summary>
/// <param name = "itemIdOZ">Itemid</param>
/// <param name = "bOMId">BOMId</param>
/// <param name = "itemId">Itemid</param>
/// <param name = "itemIdBom">Itemid</param>
/// <param name = "update">boolean</param>
/// <returns>NDXProdIdentOZMappingLine</returns>
static NDXProdIdentOZMappingLine find(Itemid itemIdOZ,
                                    BOMId bOMId,
                                    ItemId itemId,
                                    Itemid itemIdBom,
                                    boolean update = false)
{
    NDXProdIdentOZMappingLine nDXProdIdentOZMappingLine;
    if (bOMId && itemId)
    {
        nDXProdIdentOZMappingLine.selectForUpdate(update);

        select firstonly nDXProdIdentOZMappingLine
        where nDXProdIdentOZMappingLine.ItemIdOZ == itemIdOZ &&
              nDXProdIdentOZMappingLine.BOMId == bOMId &&
              nDXProdIdentOZMappingLine.ItemId == itemId &&
              nDXProdIdentOZMappingLine.itemIdBom == itemIdBom;
    }
    return nDXProdIdentOZMappingLine;
}

/// <summary>
/// PaffH 24.10.23
/// </summary>
/// <param name = "itemIdOZ">Itemid</param>
/// <param name = "bOMId">BOMId</param>
/// <param name = "itemId">Itemid</param>
/// <param name = "itemIdBom">Itemid</param>
/// <param name = "level">int</param>
/// <param name = "doWrite">boolean</param>
/// <returns>NDXProdIdentOZMappingLine</returns>
static NDXProdIdentOZMappingLine findOrCreate(Itemid itemIdOZ,
                                            BOMId bOMId,
                                            ItemId itemId,
                                            ItemId itemIdBom,
                                            int level,
                                            boolean doWrite = false)
{
    NDXProdIdentOZMappingLine nDXProdIdentOZMappingLine;
    nDXProdIdentOZMappingLine = NDXProdIdentOZMappingLine::find(itemIdOZ, bOMId, itemId, itemIdBom, true);
    if (!nDXProdIdentOZMappingLine)
    {
        nDXProdIdentOZMappingLine.ItemIdOZ = itemIdOZ;
        nDXProdIdentOZMappingLine.BOMId = bOMId;
        nDXProdIdentOZMappingLine.ItemId = itemId;
        nDXProdIdentOZMappingLine.ItemIdBOM = itemIdBom;
        nDXProdIdentOZMappingLine.Level = level;

        if (doWrite)
        {
            nDXProdIdentOZMappingLine.insert();
        }
    }
    if (nDXProdIdentOZMappingLine.Level != level)
    {
        nDXProdIdentOZMappingLine.Level = level;
        if (doWrite)
        {
            ttsbegin;
            nDXProdIdentOZMappingLine.update();
            ttscommit;
        }
    }

    return nDXProdIdentOZMappingLine;
}

/// <summary>
/// PaffH 24.10.23
/// </summary>
/// <param name = "itemIdOz">ItemId</param>
/// <returns>int</returns>
static int assignements(ItemId itemIdOz)
{
    return int642int((select count(recid) from NDXProdIdentOZMappingLine where NDXProdIdentOZMappingLine.ItemIdOZ == itemIdOz).recId);
}
